<?php if(!$available): ?><div class="alert alert-info">Import migration 19 in phpMyAdmin first.</div><?php else: ?><section class="card"><div class="card-body"><p class="text-secondary">The dates define which appointment starts belong to this administration. They do not end appointments automatically. Inactive terms remain available in history.</p><form method="post" action="<?= e(url('executive_term_edit',$term?['id'=>$term['id']]:[])) ?>"><?= csrf() ?><input type="hidden" name="_action" value="executive_term_save"><?php if($term): ?><input type="hidden" name="id" value="<?= e($term['id']) ?>"><input type="hidden" name="version" value="<?= e($term['updated_at']) ?>"><?php endif; ?><?= input('name','Administration / term name',$values['name'],'text',true,'maxlength="160"') ?><div class="row"><div class="col-md-6"><?= input('starts_on','Term start',$values['starts_on'],'date',true) ?></div><div class="col-md-6"><?= input('ends_on','Term end',$values['ends_on'],'date',true) ?></div></div><div class="mb-3"><label class="form-label" for="term-description">Description (optional)</label><textarea class="form-control" id="term-description" name="description" maxlength="1000" rows="3"><?= e($values['description']??'') ?></textarea></div><?= select_field('is_active','Availability',['1'=>'Active — available for grouping','0'=>'Inactive — keep existing history'],$values['is_active']) ?><button class="btn btn-primary">Save term</button> <a class="btn btn-light" href="<?= e(url('executive_terms')) ?>">Cancel</a></form></div></section><?php endif; ?>
